143	  onClose,
144	  title,
145	  titleId,
146	  titleStyle = 'large',
147	  labelledBy,
148	  ariaLabel,
149	  boxedHeader,
150	  contentStyles,
151	  headerStyles,
152	  headerTitleStyles,
