161	  // state, which ZimmDrawer never renders (no header sub-component in this tree) — so it
162	  // always resolves to undefined regardless of what's passed in above. Set it directly so the
163	  // `title` and `labelledBy` prop variants of ZimmDrawerProps actually work.
164	  if (title && titleId) {
165	    dialogProps['aria-labelledby'] = titleId;
166	  } else if (labelledBy) {
167	    dialogProps['aria-labelledby'] = labelledBy;
168	  }
169	  const containerProps = getDialogContainerProps();
170	
171	  return (
172	    <ModalFocusScope>
173	      <chakra.div {...containerProps} __css={{ position: 'fixed', inset: 0, display: 'flex', zIndex: 'modal' }}>
