175	          {...dialogProps}
176	          initial={{ x: '100%' }}
177	          animate={{ x: 0 }}
178	          exit={{ x: '100%' }}
179	          transition={DRAWER_TRANSITION}
180	          __css={{ position: 'fixed', top: 0, right: 0, bottom: 0, outline: 0, ...contentStyles }}
