227	/**
228	 * Generic right-anchored slide-in drawer shell — overlay, panel, and a Figma-matched size
229	 * variant (see ZimmDrawerSize), built on Chakra's Drawer primitive (focus trap, initial focus,
230	 * focus restore, body-scroll lock, and Escape/overlay-click-to-close all come from Chakra, not
231	 * hand-rolled).
232	 *
233	 * Pass `title` to render an inline header row (title text left, close button right) sized per the
234	 * Figma drawer/header frames. Omit `title` and pass `labelledBy`/`aria-label` instead for drawers
235	 * that supply their own header (e.g. ZimmPdpDrawer's tab row) — the close button floats on its own
236	 * by default. Add `boxedHeader` alongside `labelledBy` when the drawer has no header content of its
237	 * own (e.g. ZimmCountryLanguageMismatch, whose heading lives in its body) but still wants the close
238	 * button sitting in that same in-flow header row rather than floating over the content.
239	 *
240	 * @param props see ZimmDrawerProps
241	 */
242	export const ZimmDrawer = (props: ZimmDrawerProps) => {
243	  const {
244	    isOpen,
245	    onClose,
246	    size,
247	    children,
248	    titleStyle = 'large',
249	    finalFocusRef,
250	    initialFocusRef,
251	    hasOverlay = true,
252	  } = props;
253	  const styles = useMultiStyleConfig(ZIMM_DRAWER_RECIPE, { variant: size });
254	  const titleId = useId();
255	
256	  // Figma-fidelity audit fix, 2026-09-19: without an explicit `initialFocusRef`, Chakra's Drawer
257	  // defaults to auto-focusing the first focusable descendant — for every real consumer that
258	  // doesn't set one (ZimmCartDrawer, ZimmPdpDrawer), that's the close button. Reproduced live:
259	  // when nothing has focus and no prior user interaction exists yet (confirmed exactly matching
260	  // how a Storybook story that mounts already-open behaves, and plausible for a real first
261	  // render too), the browser's native `:focus-visible` heuristic has no basis to rule out a
262	  // keyboard interaction and defaults to showing the ring — on the close button, on every open,
263	  // regardless of whether the shopper used a mouse, touch, or keyboard to get there. `panelRef`
264	  // gives Chakra a neutral target instead: the dialog's own panel, `tabIndex={-1}` so it's
265	  // programmatically focusable without joining the normal Tab order. This still satisfies the
266	  // real requirement (focus moves into the dialog immediately, so keyboard/AT users land
267	  // somewhere sane and Tab/Escape work correctly from there) without ever auto-focusing an
268	  // interactive element nobody actually interacted with. A consumer that explicitly passes its
269	  // own `initialFocusRef` (ZimmWishlistAuthDrawer, straight to its email field) is untouched —
270	  // this only changes the *default* Chakra would otherwise have picked.
271	  const panelRef = useRef<HTMLDivElement>(null);
272	
273	  const title = 'title' in props ? props.title : undefined;
274	  const labelledBy = !title && 'labelledBy' in props ? props.labelledBy : undefined;
275	  const ariaLabel = !title && 'aria-label' in props ? props['aria-label'] : undefined;
276	  const boxedHeader = !title && 'labelledBy' in props ? props.boxedHeader : undefined;
277	
278	  // SFCC-926 — tester reported body scroll still active while any drawer is open, allowing
279	  // the page behind the overlay to scroll alongside the drawer. ZimmDrawer bypasses Chakra's
280	  // own <DrawerContent>, so blockScrollOnMount may not fire. Locking body overflow explicitly
281	  // ensures only the drawer's internal scroll area is accessible while it is open.
282	  // Uses the module-level counter so multiple open instances don't race to restore overflow.
283	  useEffect(() => {
284	    if (!isOpen) return;
285	    if (scrollLockCount === 0) {
286	      scrollLockPrev = document.body.style.overflow;
287	      document.body.style.overflow = 'hidden';
288	    }
289	    scrollLockCount++;
290	    return () => {
291	      scrollLockCount--;
292	      if (scrollLockCount === 0) {
293	        document.body.style.overflow = scrollLockPrev;
294	        scrollLockPrev = '';
295	      }
296	    };
297	  }, [isOpen]);
298	
299	  // Chakra's FocusLock remains active during the exit animation, so any focus call made
300	  // while the drawer is still mounted (rAF, close-button onClick) gets trapped and dropped.
301	  // onCloseComplete fires after the animation finishes and FocusLock is released — the only
302	  // reliable moment to restore focus. Covers both close-button click and Escape for all
303	  // consumers that pass finalFocusRef.
304	  const handleCloseComplete = () => {
305	    if (finalFocusRef) finalFocusRef.current?.focus();
306	  };
307	
308	  return (
309	    <Drawer
310	      isOpen={isOpen}
311	      onClose={onClose}
312	      placement="right"
313	      onCloseComplete={handleCloseComplete}
314	      initialFocusRef={initialFocusRef ?? panelRef}
315	    >
316	      {hasOverlay && <DrawerOverlay sx={styles.overlay} />}
317	      {/* aria-labelledby (not aria-label) for the title case: Chakra's own <DrawerContent>
318	          would clobber it with its own headingId (undefined without a DrawerHeader), but
319	          ZimmDrawerContent bypasses <DrawerContent> entirely and sets dialogProps itself
320	          (see its own comment above) — the clobbering bug this would otherwise work around
321	          doesn't apply here, so referencing the visible title node is safe and preferred. */}
322	      <ZimmDrawerContent
323	        onClose={onClose}
324	        title={title}
325	        titleId={title ? titleId : undefined}
326	        titleStyle={titleStyle}
327	        labelledBy={labelledBy}
328	        ariaLabel={ariaLabel}
329	        boxedHeader={boxedHeader}
330	        contentStyles={styles.content}
331	        headerStyles={styles.header}
332	        headerTitleStyles={styles.headerTitle}
333	        closeButtonStyles={styles.closeButton}
334	        panelRef={panelRef}
335	        headerCloseButtonStyles={styles.headerCloseButton}
336	      >
337	        {children}
338	      </ZimmDrawerContent>
339	    </Drawer>
340	  );
341	};
