import React from 'react';
import { chakra, useMultiStyleConfig } from '@chakra-ui/react';
import { ZimmIcon } from 'app/components/ui-kits/atoms/zimmIcon';
import { ZimmNavItem } from 'app/components/ui-kits/atoms/zimmNavItem';
import { useUiCopy } from 'app/hooks/useUiCopy';

const ZIMM_FOOTER_BOTTOM_BAR_RECIPE = 'ZimmFooterBottomBar';

// Locale control label. Hardcoded, and deliberately NOT fixture data — region and currency come
// from site config (config/default.js: defaultSite 'ZimmermannAU'), not Contentful, so
// FooterConfigEntry has no field for them. Set to match the site the app actually serves at
// '/'; it previously read "United States (USD) / ENG" on an AU storefront. The real fix reads
// site.l10n.defaultLocale and the site's currency via useMultiSite when the locale selector
// lands, at which point this constant goes away rather than getting a different literal.
const LOCALE_LABEL_PLACEHOLDER = 'Australia (AUD) / ENG';

type BottomBarProps = {
  copyrightYear: number;
  copyrightOwner: string;
  legalLinks: ReadonlyArray<{ label: string; href: string }>;
};

/**
 * Footer bottom bar — locale switcher (placeholder, not yet wired), copyright, and legal links.
 * Single-parent internal component (only Footer renders it), so per components.md it doesn't
 * need its own story — covered by footer/index.stories.tsx's assembly-level coverage.
 *
 * @param props see BottomBarProps
 */
export const BottomBar = ({ copyrightYear, copyrightOwner, legalLinks }: BottomBarProps) => {
  const styles = useMultiStyleConfig(ZIMM_FOOTER_BOTTOM_BAR_RECIPE, {});
  // Sourced directly, not threaded through as a prop — uiCopy is app-wide static microcopy,
  // safe to read from any component the same way useIntl() already is. Falls back to the
  // English literal with no UiCopyProvider mounted (Storybook, this component's own tests).
  const { t } = useUiCopy();
  const copyrightLabel = t('footer.copyright.label', 'Copyright');
  return (
    <chakra.div __css={styles.bar}>
      <chakra.div __css={styles.inner}>
        {/* PLACEHOLDER: wire to locale selector once available. Rendered as a non-interactive
            div, not a button, so nothing promises an action that cannot be performed (WCAG
            3.2.4 / 4.1.2) — same treatment ZimmContactIconRow gives an unusable channel.
            Label and destination are hardcoded until sourced from active locale/site config.
            Swap back to a real button with an onClick when the selector lands. */}
        <chakra.div __css={styles.localeButton}>
          {/* localeText = Figma "footer-item": py-8px on text only, icon sits outside.
              Typography and colour are inherited from the parent localeButton theme. */}
          <chakra.span __css={styles.localeText}>{LOCALE_LABEL_PLACEHOLDER}</chakra.span>
          <ZimmIcon type="chevron-right" size="sm" aria-hidden={true} />
        </chakra.div>

        <chakra.div __css={styles.right}>
          {/* Copyright is a direct flex child of `right` to match Figma's flat Legal row.
              py-8px matches the legal link py used in ZimmNavItem style below. */}
          <chakra.span __css={styles.copyright}>
            {copyrightLabel} &copy; {copyrightYear} {copyrightOwner}
          </chakra.span>
          <chakra.div __css={styles.legalGrid}>
            {legalLinks.map((link) => (
              <ZimmNavItem
                key={link.label}
                href={link.href}
                label={link.label}
                inverse
                // Figma Small/Default: py-[8px] — override base h-[24px] with height:auto + vertical padding
                // width is applied via legalGrid's '& > a' child selector in bottomBar.css.ts
                sx={styles.legalLink}
              />
            ))}
          </chakra.div>
        </chakra.div>
      </chakra.div>
    </chakra.div>
  );
};

import { breakpoints } from 'app/theme/foundation';
import { DRAWER_HEADER_ROW_HEIGHT } from 'app/theme/components/zimmDrawerShared';

// Figma's actual named drawer sizes (SFCC-898) — five named sizes, not the three/four this
// file previously guessed at. Each name below matches Figma's own naming exactly, so there's
// no re-deriving which number belongs to which concept next time this file is touched:
//
//   Desktop Large — 50%  — Product Details, Filters (desktop width)
//   Tablet        — 80%  — Product Details, Filters (tablet width)
//   Desktop Small — 25%  — Notify Me, Wishlist, Find in Boutique, Regional Storefront,
//                           Cookies, Login
//   X-Large       — 82%  — Cart. SFCC-11: this is the named-size *library* annotation, not a
//                           measurement of the real Cart composition — see `WIDTH_XLARGE` below,
//                           which corrects it a second time against the actual frames.
//   Mobile        — unchanged, the baseStyle treatment every variant collapses to below `md`.
//
// An earlier revision of this file measured 82% off a Figma frame annotated "Tablet = 82% of
// screen" and used it as `small`'s (now `tablet`'s) value — that frame's annotation was wrong
// (or superseded): 82% is actually X-Large's value (Cart), a completely different drawer this
// codebase hasn't built yet, and Tablet is genuinely 80%. Corrected once confirmed directly
// against the list above, not another single frame's own label.
const WIDTH_LARGE = '50%';
const WIDTH_TABLET = '80%';
// The original width set when this drawer shell was first built (2026-08-27) — matches Figma's
// "Desktop Small" exactly. Used by every viewport-independent narrow utility drawer (Find in
// Boutique today; Notify Me/Wishlist/Regional Storefront/Cookies/Login once those exist).
const WIDTH_SMALL = '25%';
// SFCC-11 (Cart build): the "X-Large — 82%" library annotation two paragraphs up is the
// named-size *system* value, not a measurement of the actual Cart composition. Re-measured the
// real frames directly (node 9323:65888 at 1920px, node 9323:65895 at 1440px, file
// QQ427wHWEUjsjP7H8v48Rs) — the cart panel itself (frame "pdp/drawer") is a FIXED 1186px at
// both widths; the backdrop gap grows instead of the panel. 82% of 1920 is 1574px — 388px
// wider than designed. This is the same annotation-vs-measurement trap the comment above
// already records once for Tablet; it recurred here for X-Large. 74.125rem = 1186px.
// Widths/min-widths/max-widths across drawer sizes are a live, unsettled area as of
// 2026-09-17 (Marcel) — this ships to the current measured Figma spec and may be
// reconciled once that broader call is made; not a final word on the sizing model.
// audit-allow: Figma-confirmed fixed width with no --zimm-scale equivalent at this value.
const WIDTH_XLARGE = '74.125rem'; // 1186px
// The 1440px node (9323:65895) — and its own "Content Container" child, 9323:99046 — carries an
// explicit dev annotation, re-confirmed directly against that second node, 2026-09-21: "On
// devices sizes under 1440, use the 82% drawer pattern / Max width is at 1186px, beyond this
// screen size, the drawer will stay at the fixed width." That is a genuine two-regime rule, not a
// single continuous formula: below 1440px, a percentage; AT 1440px and up, the fixed width
// outright — not merely a ceiling a percentage eventually grows into.
//
// 1:1 Figma-alignment audit fix, 2026-09-21: this file used to implement that as ONE step
// (`width: 82%, maxWidth: 1186px`) spanning every width from `md` (768px) up, on the theory that
// the percentage would "naturally" reach the 1186px ceiling right around the stated 1440px
// threshold. It doesn't: 82% of the viewport only equals 1186px at a 1446.34px viewport
// (1186 / 0.82), so viewports between 1440px and 1446px rendered a few px narrower than the
// annotation's own stated rule (measured: 1180.8px at exactly 1440px, 5.2px short). Fixed by
// giving the fixed-width regime its own explicit breakpoint below (`XLARGE_FIXED_BREAKPOINT`,
// 1440px) instead of relying on the percentage to converge there — same "percentage-with-an-
// explicit-floor" shape `PANEL_MIN_NARROW` already established for `small`/`prompt` below, for
// the identical class of bug (a percentage meant to reach a fixed pixel target, arriving late).
//
// This constant itself is now genuinely tablet-only (768px–1439px) rather than the misleadingly-
// named shared value it used to be, since the new fixed step below always wins from 1440px up
// regardless of what this one computes to. The tablet question this constant's own number still
// carries — Figma's stated 82% vs. the live tablet frame's own 659.2px/79.06% measurement — is
// untouched by this fix and remains open (see the file-level docblock two paragraphs up).
const WIDTH_XLARGE_TABLET = '82%';
// Figma's own stated threshold for X-Large's fixed-width regime (see WIDTH_XLARGE_TABLET's own
// comment above) — no existing breakpoint token lands on it (`lg` 992px, `xl` 1280px, `2xl`
// 1536px) — audit-allow: Figma-confirmed threshold, no --zimm-scale/breakpoints equivalent.
const XLARGE_FIXED_BREAKPOINT = '90em'; // 1440px

// PDP drawer leaves a strip of backdrop visible below the panel on mobile (SFCC-736 AC 9,
// PO-approved 2026-08-21 — "so a user can easily navigate out"). Re-measured against node
// 40002218:42903 (SFCC-898): overlay 956px tall, panel 898px tall — exactly 58px. Only the
// `mobileGap` variant opts into this; the baseStyle defaults to full-height so utility
// drawers (wishlist auth, etc.) don't need to explicitly override it. No named spacing scale
// step lands on 58px — provisional raw value pending a foundation token.
const MOBILE_BOTTOM_GAP = '3.625rem'; // 58px

// Close-button inset, measured from the pdp/drawer header frames. `tablet`/`small`/`xLarge`/
// `mobile` all share the same measured inset (32px/40px) at every width — only `large` switches
