  onSendCode: () => Promise<{ success: boolean; error?: string } | void> | void;
  onSignInWithApple?: () => void;
  onSignInWithGoogle?: () => void;
  onCreateAccount: () => void;
  socialEnabled?: boolean;
  /** Error message to display below the social sign-in buttons (e.g. IDP redirect failure). */
  socialError?: string;
  /** When false the email/OTP form is hidden — passwordless login is not configured for this site. */
  passwordlessEnabled?: boolean;
  isLoading?: boolean;
  /** Forwarded to the email input — pass the same ref given to ZimmDrawer's initialFocusRef
   *  so focus lands on the input (not the close button) when the drawer opens. */
  initialFocusRef?: React.RefObject<HTMLInputElement>;
};

/**
 * Zimmermann-branded login view rendered inside ZimmDrawer for the wishlist auth panel.
 * Composes email form, optional social sign-in, and create-account sections (SFCC-742).
 */
export const ZimmAuthDrawerContent = ({
  description,
  emailValue,
  onEmailChange,
  onSendCode,
  onSignInWithApple,
  onSignInWithGoogle,
  onCreateAccount,
  socialEnabled = false,
  passwordlessEnabled = true,
  isLoading = false,
  socialError,
  initialFocusRef,
}: ZimmAuthDrawerContentProps) => {
  const styles = useMultiStyleConfig(ZIMM_AUTH_DRAWER_CONTENT_RECIPE, {});

  const showSocial = socialEnabled && (!!onSignInWithApple || !!onSignInWithGoogle);

  return (
    <chakra.div __css={styles.root}>
      <chakra.div __css={styles.content}>
        {description && <chakra.p __css={styles.description}>{description}</chakra.p>}
        {passwordlessEnabled && (
          <chakra.div __css={styles.emailForm}>
            <EmailForm
              emailValue={emailValue}
              onEmailChange={onEmailChange}
              onSubmit={onSendCode}
              isLoading={isLoading}
              inputRef={initialFocusRef}
            />
          </chakra.div>
        )}
      </chakra.div>

      {showSocial && (
        <>
          <chakra.div __css={styles.divider} aria-hidden={true} />
          <chakra.div __css={styles.socialGroup}>
            <SocialButtons onSignInWithApple={onSignInWithApple} onSignInWithGoogle={onSignInWithGoogle} />
            {socialError && (
              <chakra.p role="alert" __css={styles.socialError}>
                {socialError}
              </chakra.p>
            )}
          </chakra.div>
        </>
      )}

