import React from 'react';
import { Box, Stack, Text } from '@chakra-ui/react';
import { useIntl, defineMessages } from 'react-intl';
import { ZimmCheckbox } from 'app/components/ui-kits/atoms/zimmCheckbox';

const messages = defineMessages({
  comingSoon: {
    id: 'ZimmCheckboxGroup.comingSoon',
    defaultMessage: 'Coming soon',
  },
});

// audit-allow: 368px — Figma node 40003890; derived ~32px/item × 12 items. No foundation token.
const maxHeight = '368px';

export type ZimmCheckboxGroupOption = {
  value: string;
  label: string;
  /** When 0 and not selected the option is hidden — pass undefined to always show. */
  hitCount?: number;
  /** Renders a filled colour dot beside the label when set (e.g. a CSS colour string). */
  swatchColour?: string;
};

type ZimmCheckboxGroupProps = {
  options: readonly ZimmCheckboxGroupOption[];
  selectedValues: readonly string[];
  /** Called with the option value and whether it was already selected (true = deselect). */
  onChange: (value: string, isCurrentlySelected: boolean) => void;
};

/**
 * Generic checkbox list for multi-select filtering. Not tied to SFCC or any specific data
 * shape — accepts plain option objects so it can be used in filter drawers, preference forms,
 * or any multi-select surface.
 *
 * Each row is a `ZimmCheckbox` atom; hit-count visibility and swatch rendering are
 * delegated there.
 */
export const ZimmCheckboxGroup = ({ options, selectedValues, onChange }: ZimmCheckboxGroupProps) => {
  const intl = useIntl();

  const hasVisibleOptions = options.some(
    (opt) => opt.hitCount !== 0 || selectedValues.includes(opt.value),
  );

  if (!hasVisibleOptions) {
    return (
      <Text textStyle="body2" color="var(--zimm-color-text-muted)">
        {intl.formatMessage(messages.comingSoon)}
      </Text>
    );
  }

  return (
    <Box
      maxHeight={maxHeight}
      overflowY="auto"
      paddingLeft="var(--zimm-scale-2xs)"
    >
      <Stack spacing="var(--zimm-scale-m)">
        {options.map((option) => (
          <ZimmCheckbox
            key={option.value}
            value={option.value}
            label={option.label}
            hitCount={option.hitCount}
            swatchColour={option.swatchColour}
            isChecked={selectedValues.includes(option.value)}
            onChange={onChange}
          />
        ))}
      </Stack>
    </Box>
  );
};
